window.STORIES={"1":{"id":1,"name":"الخليقة","disp":"تكوين ١: ١–٣١","ref":"التكوين 1:1","text":"ربنا خلق السما والأرض والشمس والقمر والنجوم والزرع والحيوانات، وفي الآخر خلق الإنسان على صورته، وشاف كل حاجة عملها إنها حسنة جدًا."},"2":{"id":2,"name":"نوح والفلك","disp":"تكوين ٦: ٩ – ٩: ١٧","ref":"التكوين 6:9","text":"نوح سمع كلام الله وبنى فلك كبير ودخل فيه هو وعيلته والحيوانات، ولما الطوفان جه الله حفظهم، وحط قوس قزح علامة لوعده."},"3":{"id":3,"name":"إبراهيم يطيع الله","disp":"تكوين ١٢: ١–٥","ref":"التكوين 12:1","text":"الله قال لإبراهيم: اخرج من أرضك للأرض اللي هاوريهالك. وإبراهيم صدّق الله وخرج وهو مش عارف رايح فين."},"4":{"id":4,"name":"إسحق ابن الوعد","disp":"تكوين ٢١: ١–٧","ref":"التكوين 21:1","text":"الله وعد إبراهيم وسارة بابن وهما كبار جدًا، وفي الوقت اللي حدده الله اتولد إسحق، وسارة ضحكت من الفرحة."},"5":{"id":5,"name":"يوسف يسامح إخوته","disp":"تكوين ٤٥: ١–١٥","ref":"التكوين 45:1","text":"إخوات يوسف باعوه وهو صغير، والله كان معاه. ولما بقى عظيم في مصر سامحهم وحضنهم وقال لهم: الله حوّل الشر لخير."},"6":{"id":6,"name":"يوسف الأمين","disp":"تكوين ٣٩: ١–٦","ref":"التكوين 39:1","text":"يوسف كان أمين في كل شغل اتطلب منه في بيت فوطيفار، والرب كان معاه وبارك كل حاجة في إيده."},"7":{"id":7,"name":"موسى في السفط","disp":"خروج ٢: ١–١٠","ref":"الخروج 2:1","text":"أم موسى حطته في سفط صغير على النهر، وأخته مريم كانت بتراقبه، والله حفظه وبنت فرعون لقته وربّته."},"10":{"id":10,"name":"الحية النحاسية","disp":"عدد ٢١: ٤–٩","ref":"سفر العدد 21:4","text":"الشعب اتلدغ من الحيات، والله قال لموسى يعمل حية من نحاس على عمود، وكل اللي بص لها عاش. ويسوع قال إنه هيترفع على الصليب كده علشان كل اللي يؤمن بيه يعيش."},"11":{"id":11,"name":"أسوار أريحا","disp":"يشوع ٦: ١–٢٠","ref":"يشوع 6:1","text":"يشوع والشعب سمعوا كلام الله ولفوا حوالين أسوار أريحا سبع أيام، وفي اليوم السابع هتفوا والأسوار وقعت."},"12":{"id":12,"name":"صموئيل يسمع صوت الله","disp":"١ صموئيل ٣: ١–١٠","ref":"صموئيل الأول 3:1","text":"صموئيل كان ولد صغير، وبالليل سمع صوت بيناديه، وفي الآخر قال: تكلم يا رب لأن عبدك سامع."},"13":{"id":13,"name":"حنة تصلي","disp":"١ صموئيل ١: ٩–٢٠","ref":"صموئيل الأول 1:9","text":"حنة كانت حزينة علشان ماعندهاش أولاد، فصلّت لله من كل قلبها، والله سمع صلاتها وإدّاها صموئيل."},"14":{"id":14,"name":"داود الراعي الشجاع","disp":"١ صموئيل ١٧: ٣٤–٣٧","ref":"صموئيل الأول 17:34","text":"داود كان راعي صغير، ولما أسد ودب جم ياخدوا خروف، الرب ساعده ينقذ الخروف. كان بيحب غنمه وبيحميها."},"15":{"id":15,"name":"داود وجليات","disp":"١ صموئيل ١٧: ٣٢–٥٠","ref":"صموئيل الأول 17:32","text":"جليات كان جبار والكل خايف منه، لكن داود الصغير قال: أنا جاي لك باسم رب الجنود، وبحجر صغير الله نصره."},"16":{"id":16,"name":"داود ويوناثان","disp":"١ صموئيل ١٨: ١–٤","ref":"صموئيل الأول 18:1","text":"يوناثان ابن الملك حب داود زي نفسه، وإدّاه هدومه وسيفه، وفضلوا أصحاب أوفياء."},"17":{"id":17,"name":"إيليا والغربان","disp":"١ ملوك ١٧: ١–٦","ref":"الملوك الأول 17:1","text":"وقت المجاعة الله بعت غربان تجيب لإيليا عيش ولحمة الصبح وبالليل، والله اعتنى بيه."},"18":{"id":18,"name":"الأرملة والدقيق","disp":"١ ملوك ١٧: ٨–١٦","ref":"الملوك الأول 17:8","text":"أرملة فقيرة كان عندها شوية دقيق وزيت بس، وعملت لإيليا رغيف الأول، والله خلّى الدقيق والزيت ما يخلصوش."},"19":{"id":19,"name":"نعمان والبنت الصغيرة","disp":"٢ ملوك ٥: ١–١٤","ref":"الملوك الثاني 5:1","text":"بنت صغيرة كانت خدامة في بيت نعمان، وقالت لسيدتها عن نبي الله، ونعمان راح واتشفى."},"20":{"id":20,"name":"دانيال وأصحابه في القصر","disp":"دانيال ١: ٨–٢٠","ref":"دانيال 1:8","text":"دانيال وأصحابه كانوا صغيرين في قصر الملك، وقرروا يرضوا الله وما ياكلوش أكل الملك، والله إداهم صحة وحكمة أكتر من الكل."},"21":{"id":21,"name":"دانيال في جب الأسود","disp":"دانيال ٦: ١٠–٢٣","ref":"دانيال 6:10","text":"دانيال فضل يصلي لله حتى لما الملك منع الصلاة، فرموه في جب الأسود، والله بعت ملاكه وسد أفواه الأسود."},"22":{"id":22,"name":"يونان والحوت","disp":"يونان ١: ١ – ٢: ١٠","ref":"يونان 1:1","text":"يونان هرب من كلام الله، والحوت بلعه، وفي بطن الحوت صلّى وتاب، والله أنقذه وراح نينوى."},"23":{"id":23,"name":"النملة الحكيمة","disp":"أمثال ٦: ٦–٨","ref":"الأمثال 6:6","text":"الكتاب بيقول: روح للنملة وشوف هي بتشتغل إزاي؛ بتجمع أكلها في الصيف من غير ما حد يقول لها."},"24":{"id":24,"name":"ميلاد يسوع والرعاة","disp":"لوقا ٢: ٨–٢٠","ref":"لوقا 2:8","text":"الرعاة كانوا بيحرسوا الغنم بالليل، والملاك قال لهم: وُلد لكم مخلص. راحوا لقوا الطفل يسوع في المذود وفرحوا ومجدوا الله."},"25":{"id":25,"name":"المجوس والنجم","disp":"متى ٢: ١–١٢","ref":"متى 2:1","text":"مجوس من الشرق مشيوا ورا نجم لحد ما وصلوا للطفل يسوع، وسجدوا له وقدّموا له ذهب ولبان ومر."},"26":{"id":26,"name":"يسوع في الهيكل وعمره ١٢ سنة","disp":"لوقا ٢: ٤١–٥٢","ref":"لوقا 2:41","text":"يسوع وهو عنده ١٢ سنة قعد في الهيكل يسمع ويسأل، وبعدين رجع مع مريم ويوسف وكان خاضع لهم، وكان بيكبر في الحكمة والنعمة."},"27":{"id":27,"name":"يسوع يبارك الأطفال","disp":"مرقس ١٠: ١٣–١٦","ref":"مرقس 10:13","text":"الناس جابوا أولادهم ليسوع والتلاميذ منعوهم، لكن يسوع قال: دعوا الأولاد يأتون إليّ، وحضنهم وباركهم."},"28":{"id":28,"name":"صيد السمك الكتير","disp":"لوقا ٥: ١–١١","ref":"لوقا 5:1","text":"بطرس اشتغل طول الليل وما صادش حاجة، ولما سمع كلام يسوع ورمى الشبكة اتملت سمك، وساب كل حاجة ومشي ورا يسوع."},"29":{"id":29,"name":"يسوع يهدّي العاصفة","disp":"مرقس ٤: ٣٥–٤١","ref":"مرقس 4:35","text":"التلاميذ كانوا في المركب والعاصفة شديدة وخافوا، ويسوع قام وقال للريح والبحر: اسكت، فبقى هدوء عظيم."},"30":{"id":30,"name":"بطرس يمشي على الماء","disp":"متى ١٤: ٢٢–٣٣","ref":"متى 14:22","text":"يسوع جه ماشي على المية، وبطرس نزل يمشي ناحيته، ولما بص للموج خاف وابتدا يغرق، فيسوع مد إيده ومسكه."},"31":{"id":31,"name":"الولد والخمس خبزات","disp":"يوحنا ٦: ١–١٣","ref":"يوحنا 6:1","text":"ولد صغير قدّم ليسوع خمس خبزات وسمكتين، ويسوع شكر وبارك وأكّل منهم أكتر من خمس آلاف واحد وفضل كمان."},"32":{"id":32,"name":"بارتيماوس الأعمى","disp":"مرقس ١٠: ٤٦–٥٢","ref":"مرقس 10:46","text":"بارتيماوس كان أعمى وقاعد على الطريق، ولما سمع إن يسوع معدّي صرخ: يا يسوع ارحمني، ويسوع فتح عينيه ومشي وراه."},"33":{"id":33,"name":"بنت يايرس","disp":"مرقس ٥: ٣٥–٤٣","ref":"مرقس 5:35","text":"بنت صغيرة عندها ١٢ سنة ماتت، ويسوع مسك إيدها وقال لها: يا صبية قومي، فقامت ومشيت."},"34":{"id":34,"name":"العشرة البرص","disp":"لوقا ١٧: ١١–١٩","ref":"لوقا 17:11","text":"يسوع شفى عشرة رجالة عيانين، وواحد بس رجع يشكره ويمجد الله بصوت عالي."},"35":{"id":35,"name":"زكا العشار","disp":"لوقا ١٩: ١–١٠","ref":"لوقا 19:1","text":"زكا كان قصير وطلع على شجرة جميز علشان يشوف يسوع، ويسوع ناداه باسمه ودخل بيته، وزكا اتغير ورجّع الفلوس اللي أخدها."},"36":{"id":36,"name":"السامري الصالح","disp":"لوقا ١٠: ٣٠–٣٧","ref":"لوقا 10:30","text":"راجل اتضرب على الطريق، وناس كتير عدّوا من غير ما يساعدوه، لكن السامري وقف وربط جروحه واعتنى بيه."},"37":{"id":37,"name":"الخروف الضال","disp":"لوقا ١٥: ٤–٧","ref":"لوقا 15:4","text":"راعي عنده ١٠٠ خروف وواحد تاه، ساب التسعة والتسعين ودوّر عليه لحد ما لقاه، وشاله على كتافه فرحان."},"38":{"id":38,"name":"الابن الضال","disp":"لوقا ١٥: ١١–٢٤","ref":"لوقا 15:11","text":"ابن ساب بيت أبوه وصرف كل فلوسه، ولما رجع تايب، أبوه جري عليه وحضنه وعمل له فرح كبير."},"39":{"id":39,"name":"مريم عند رجلين يسوع","disp":"لوقا ١٠: ٣٨–٤٢","ref":"لوقا 10:38","text":"مرثا كانت مشغولة بحاجات كتير، ومريم قعدت عند رجلين يسوع تسمع كلامه، ويسوع قال إن مريم اختارت النصيب الصالح."},"40":{"id":40,"name":"فلسا الأرملة","disp":"مرقس ١٢: ٤١–٤٤","ref":"مرقس 12:41","text":"أرملة فقيرة حطت فلسين بس في صندوق العطاء، ويسوع قال إنها إدّت أكتر من الكل لأنها إدّت كل اللي عندها."},"41":{"id":41,"name":"البيت على الصخر","disp":"متى ٧: ٢٤–٢٧","ref":"متى 7:24","text":"الراجل العاقل بنى بيته على الصخر، فلما المطر نزل فضل ثابت؛ واللي بيسمع كلام يسوع ويعمل بيه زي الراجل ده."},"42":{"id":42,"name":"مثل الزارع","disp":"لوقا ٨: ٤–١٥","ref":"لوقا 8:4","text":"الزارع رمى البذار؛ البذرة اللي وقعت في الأرض الجيدة طلعت ثمر كتير، والبذرة هي كلمة الله."},"43":{"id":43,"name":"حبة الخردل","disp":"متى ١٣: ٣١–٣٢","ref":"متى 13:31","text":"حبة الخردل أصغر بذرة، لكن لما تتزرع تكبر وتبقى شجرة والطيور تسكن فيها."},"44":{"id":44,"name":"العذارى الحكيمات","disp":"متى ٢٥: ١–١٣","ref":"متى 25:1","text":"خمس بنات حكيمات خدوا زيت زيادة لمصابيحهم وكانوا مستعدين لما العريس جه؛ وإحنا كمان لازم نكون مستعدين لمجيء يسوع."},"45":{"id":45,"name":"الفريسي والعشار","disp":"لوقا ١٨: ٩–١٤","ref":"لوقا 18:9","text":"الفريسي صلّى وهو فخور بنفسه، والعشار وقف بعيد وقال: اللهم ارحمني أنا الخاطي، والعشار هو اللي رجع مبرّر."},"46":{"id":46,"name":"يسوع يغسل الأرجل","disp":"يوحنا ١٣: ١–١٥","ref":"يوحنا 13:1","text":"يسوع ربط منشفة وغسل رجلين تلاميذه، وقال لهم: اعملوا لبعض زي ما أنا عملت لكم."},"47":{"id":47,"name":"اللص التائب","disp":"لوقا ٢٣: ٣٩–٤٣","ref":"لوقا 23:39","text":"لص كان على الصليب جنب يسوع قال له: اذكرني يا رب، ويسوع قال له: اليوم تكون معي في الفردوس."},"48":{"id":48,"name":"القبر الفاضي","disp":"متى ٢٨: ١–١٠","ref":"متى 28:1","text":"الستات راحوا للقبر بدري، والملاك قال لهم: ليس هو ههنا لأنه قام، ورجعوا يجروا فرحانين يقولوا للتلاميذ."},"49":{"id":49,"name":"تلميذا عمواس","disp":"لوقا ٢٤: ١٣–٣٥","ref":"لوقا 24:13","text":"اتنين من التلاميذ كانوا ماشيين زعلانين، ويسوع مشي معاهم وكلمهم من الكتاب، ولما عرفوه قلبهم بقى فرحان."},"50":{"id":50,"name":"صعود يسوع","disp":"أعمال ١: ٩–١١","ref":"أعمال الرسل 1:9","text":"يسوع اترفع للسما قدام التلاميذ، والملايكة قالوا لهم: يسوع ده هييجي تاني بنفس الطريقة."},"51":{"id":51,"name":"يوم الخمسين","disp":"أعمال ٢: ١–٤","ref":"أعمال الرسل 2:1","text":"التلاميذ كانوا مجتمعين بيصلّوا، والروح القدس نزل عليهم، وبقوا شجعان يكلموا الناس عن يسوع."},"52":{"id":52,"name":"الكنيسة الأولى","disp":"أعمال ٢: ٤٢–٤٧","ref":"أعمال الرسل 2:42","text":"المؤمنين الأوائل كانوا بيسمعوا كلام الله ويصلّوا ويشاركوا بعض في كل حاجة بفرح ومحبة."},"53":{"id":53,"name":"الكنيسة تصلي لبطرس","disp":"أعمال ١٢: ٥–١٧","ref":"أعمال الرسل 12:5","text":"بطرس كان في السجن والكنيسة كلها بتصلي علشانه، والله بعت ملاك فك السلاسل وفتح له الباب."},"54":{"id":54,"name":"بولس وسيلا يسبحان","disp":"أعمال ١٦: ٢٥–٣٤","ref":"أعمال الرسل 16:25","text":"بولس وسيلا كانوا في السجن وبالليل بيسبحوا الله، وحصلت زلزلة والأبواب اتفتحت، والسجان آمن بيسوع هو وعيلته."},"55":{"id":55,"name":"شاول يقابل يسوع","disp":"أعمال ٩: ١–١٩","ref":"أعمال الرسل 9:1","text":"شاول كان بيضطهد المؤمنين، ونور من السما لمع حواليه وسمع صوت يسوع، واتغير قلبه وبقى بولس الرسول."},"56":{"id":56,"name":"طابيثا تخدم الناس","disp":"أعمال ٩: ٣٦–٤٢","ref":"أعمال الرسل 9:36","text":"طابيثا كانت بتخيّط هدوم للفقرا وبتعمل خير كتير، والكل كان بيحبها علشان خدمتها."},"57":{"id":57,"name":"المرأة السامرية","disp":"يوحنا ٤: ٥–٣٠","ref":"يوحنا 4:5","text":"يسوع كلم ست عند البير عن الماء الحي، وهي جريت للبلد كلها تقول: تعالوا شوفوا!"},"58":{"id":58,"name":"يسوع يغلب إبليس","disp":"متى ٤: ١–١١","ref":"متى 4:1","text":"إبليس جرّب يسوع في البرية، ويسوع ردّ عليه كل مرة بكلام الكتاب: مكتوب… وإبليس مشي."},"59":{"id":59,"name":"الكرمة والأغصان","disp":"يوحنا ١٥: ١–٨","ref":"يوحنا 15:1","text":"يسوع قال: أنا الكرمة وأنتم الأغصان؛ الغصن الثابت في الكرمة بيطلع ثمر كتير."},"60":{"id":60,"name":"يسوع بيعدّ لنا مكان","disp":"يوحنا ١٤: ١–٣","ref":"يوحنا 14:1","text":"يسوع قال لتلاميذه: ما تخافوش، أنا رايح أعد لكم مكان في بيت أبويا، وهارجع آخدكم معايا."},"61":{"id":61,"name":"السماء الجديدة","disp":"رؤيا ٢١: ١–٤","ref":"الرؤيا 21:1","text":"يوحنا شاف السما الجديدة؛ مكان مافيهوش دموع ولا وجع ولا حزن، والله نفسه هيكون مع شعبه."},"63":{"id":63,"name":"الأطفال يهتفون ليسوع","disp":"متى ٢١: ١٥–١٦","ref":"متى 21:15","text":"لما يسوع دخل الهيكل الأطفال هتفوا: أوصنا لابن داود، ويسوع فرح بتسبيحهم."},"64":{"id":64,"name":"يشوع: تشدد وتشجع","disp":"يشوع ١: ١–٩","ref":"يشوع 1:1","text":"يشوع كان هيقود الشعب بعد موسى، والله قال له: تشدد وتشجع، لا ترهب لأن الرب إلهك معك."},"67":{"id":67,"name":"العظام اليابسة","disp":"حزقيال ٣٧: ١–١٠","ref":"حزقيال 37:1","text":"الله ورّى حزقيال وادي مليان عظام ناشفة، ولما اتكلم بكلام الله رجعت فيها الحياة."},"69":{"id":69,"name":"المفلوج وأصحابه الأربعة","disp":"مرقس ٢: ١–١٢","ref":"مرقس 2:1","text":"أربع أصحاب شالوا صاحبهم العيان ونزلوه من السقف قدام يسوع، ويسوع شافهم مؤمنين وشفاه."}};
